package com.brightloop.payment;import java.math.BigDecimal;import java.time.Instant;import java.util.List;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;
public interface PaymentRepository extends JpaRepository<Payment,Long>{List<Payment> findByCustomerId(Long customerId);List<Payment> findByCustomerEmailIgnoreCase(String email);@Query("select coalesce(sum(p.amount),0) from Payment p where p.status='COMPLETED'") BigDecimal totalCollected();List<Payment> findByPaymentDateBetween(Instant from,Instant to);@Query("select p.paymentMethod,count(p),coalesce(sum(p.amount),0) from Payment p where p.status='COMPLETED' and p.paymentDate between :from and :to group by p.paymentMethod order by sum(p.amount) desc") List<Object[]> totalsByMethod(Instant from,Instant to);}
